const p = $input.first().json.body;
const formatFor = (mime) => (mime || '').includes('mp4') ? 'mp4' : (mime || '').includes('wav') ? 'wav' : (mime || '').includes('mpeg') ? 'mp3' : 'webm';
const system = "You are an examiner for the Dutch Inburgering A2 speaking exam (Spreken).\nYou receive one exam question: its block type, the instruction, the question text, key points a good answer covers, an optional picture description, a reference answer and the candidate audio.\nBlock types by pictureCount: 0 = listen to the question and answer in one or two sentences; 1 = describe at least three things on the picture; 2 = choose one of two pictures and explain why; 3 = name all pictures and say what you can do with them.\nStep 1: transcribe the candidate audio in Dutch. Ignore hesitation words. If there is no audio, use the speech hint as transcript.\nStep 2: grade the transcript for task completion, vocabulary and grammar. Ignore punctuation, capitalisation and obvious recognition errors. Judge the language the candidate actually produced.\nReply with JSON only, no markdown, in this shape:\n{\"transcript\": \"<Dutch transcript>\", \"score\": <integer 0-10>, \"completed\": <true or false>, \"strengths\": [\"<English>\"], \"missingPoints\": [\"<key points not covered>\"], \"mistakes\": [{\"original\": \"<exact fragment from transcript>\", \"correction\": \"<Dutch correction>\", \"explanation\": \"<short English explanation of the rule>\"}], \"feedback\": \"<2-3 sentences in English with the most useful advice>\"}\nList at most 6 mistakes, the most important first. If there are no mistakes return an empty array.";
const userText = ['Block pictureCount: ' + p.pictureCount + ' (0 = audio-only question)', 'Instruction (Dutch): ' + p.instruction, 'Question (Dutch): ' + (p.question || 'audio only, not shown to candidate'), 'Key points: ' + (p.keyPoints || []).join('; '), 'Picture description: ' + (p.pictureDescription || 'none'), 'Reference answer (Dutch): ' + (p.referenceAnswer || 'none'), 'Browser speech hint (may be wrong or empty): ' + (p.transcriptHint || 'none')].join('\n');
const content = [{ type: 'text', text: userText }];
if (p.audio && p.audio.base64) content.push({ type: 'input_audio', input_audio: { data: p.audio.base64, format: formatFor(p.audio.mimeType) } });
const messages = [{ role: 'system', content: system }, { role: 'user', content }];
const freeContent = [{ type: 'text', text: userText + '\nNo audio is attached. Use the browser speech hint as the transcript.' }];
const freeMessages = [{ role: 'system', content: system }, { role: 'user', content: freeContent }];
const freeModel = (p.transcriptHint || '').trim() ? 'nvidia/nemotron-3.5-super-vl:free' : '';
return [{ json: { freeModel, paidModel: 'google/gemini-2.5-flash', messages, freeMessages } }];

const raw = $input.first().json.choices[0].message.content;
const start = raw.indexOf('{');
const end = raw.lastIndexOf('}');
if (start === -1 || end <= start) throw new Error('Model reply contained no JSON');
return [{ json: JSON.parse(raw.slice(start, end + 1)) }];
